package com.gameaggregator.revenueservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.revenueservice.application.RevenueService;import com.gameaggregator.revenueservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/revenue-rules") public class RevenueController{final RevenueService s;public RevenueController(RevenueService s){this.s=s;}@PostMapping ApiResponse<RevenueRule> create(@Valid @RequestBody RevenueDtos.CreateRule r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<RevenueRule>> list(){return ApiResponse.success(s.list());}@PostMapping("/{id}/versions")ApiResponse<RevenueRuleVersion> version(@PathVariable UUID id,@Valid @RequestBody RevenueDtos.CreateVersion r){return ApiResponse.success(s.version(id,r));}@GetMapping("/{id}/versions")ApiResponse<List<RevenueRuleVersion>> versions(@PathVariable UUID id){return ApiResponse.success(s.versions(id));}}